const pptxgen = require("pptxgenjs");

let pres = new pptxgen();
pres.layout = 'LAYOUT_16x9'; // 10 x 5.625
pres.author = 'Gemini CLI';
pres.title = "Generative AI's Act Two: From Technology Hammer to Real Value";

// Colors
const BG_COLOR = "111827"; // Dark slate
const TEXT_LIGHT = "F9FAFB"; // Very light grey
const TEXT_MUTED = "9CA3AF"; // Gray
const ACCENT_AI = "10B981"; // Emerald
const ACCENT_INC = "3B82F6"; // Blue
const CARD_BG = "1F2937"; // Lighter dark slate
const BORDER = "374151";

// Slide Masters
pres.defineSlideMaster({
  title: 'TITLE_SLIDE', 
  background: { color: BG_COLOR },
  objects: [
    { rect: { x: 0, y: 0, w: 10, h: 5.625, fill: { color: BG_COLOR } } },
    { rect: { x: 0, y: 0.5, w: 0.15, h: 1.5, fill: { color: ACCENT_AI } } }
  ]
});

pres.defineSlideMaster({
  title: 'CONTENT_SLIDE', 
  background: { color: BG_COLOR },
  objects: [
    { rect: { x: 0, y: 0, w: 10, h: 5.625, fill: { color: BG_COLOR } } },
    { line: { x: 0.5, y: 0.9, w: 9, h: 0, line: { color: BORDER, width: 1 } } }
  ]
});

// Helpers
const makeShadow = () => ({ type: "outer", blur: 10, offset: 3, angle: 45, color: "000000", opacity: 0.3 });

// --- SLIDE 1: Title ---
let slide1 = pres.addSlide({ masterName: "TITLE_SLIDE" });
slide1.addText("Generative AI's Act Two:", {
  x: 0.5, y: 1.5, w: 9, h: 0.8, fontSize: 44, color: TEXT_LIGHT, bold: true, margin: 0, fontFace: "Helvetica Neue"
});
slide1.addText("From Technology Hammer to Real Value", {
  x: 0.5, y: 2.3, w: 9, h: 0.6, fontSize: 32, color: ACCENT_AI, bold: true, margin: 0, fontFace: "Helvetica Neue"
});

slide1.addText("Based on analysis by Sequoia Capital\nSeptember 2023", {
  x: 0.5, y: 4.0, w: 9, h: 0.8, fontSize: 18, color: TEXT_MUTED, margin: 0, fontFace: "Helvetica Neue"
});

// --- SLIDE 2: Decades of Convergence ---
let slide2 = pres.addSlide({ masterName: "CONTENT_SLIDE" });
slide2.addText("Six Decades of Technological Progress Converged", {
  x: 0.5, y: 0.3, w: 9, h: 0.6, fontSize: 24, color: TEXT_LIGHT, bold: true, margin: 0
});

// 3 Layers
const layers = [
  { title: "Moore's Law (6 Decades)", desc: "Exaflops of compute power", color: "1E3A8A", w: 8, x: 1, y: 1.5 },
  { title: "The Internet (4 Decades)", desc: "Trillions of tokens of training data", color: "1D4ED8", w: 6, x: 2, y: 2.5 },
  { title: "Mobile & Cloud (2 Decades)", desc: "Supercomputer in every pocket", color: "2563EB", w: 4, x: 3, y: 3.5 }
];

layers.forEach((l, i) => {
  slide2.addShape(pres.shapes.RECTANGLE, {
    x: l.x, y: l.y, w: l.w, h: 0.8, fill: { color: l.color }, shadow: makeShadow()
  });
  slide2.addText(`${l.title}`, {
    x: l.x, y: l.y + 0.1, w: l.w, h: 0.3, fontSize: 18, color: "FFFFFF", bold: true, align: "center", margin: 0
  });
  slide2.addText(`${l.desc}`, {
    x: l.x, y: l.y + 0.4, w: l.w, h: 0.3, fontSize: 14, color: "E2E8F0", align: "center", margin: 0
  });
});

slide2.addShape(pres.shapes.DOWN_ARROW, {
  x: 4.6, y: 4.5, w: 0.8, h: 0.6, fill: { color: ACCENT_AI }, line: { color: BG_COLOR }
});

// --- SLIDE 3: GenAI Startups Surpassed $1B ---
let slide3 = pres.addSlide({ masterName: "CONTENT_SLIDE" });
slide3.addText("GenAI Startups Surpassed $1B Revenue Faster Than SaaS", {
  x: 0.5, y: 0.3, w: 9, h: 0.6, fontSize: 24, color: TEXT_LIGHT, bold: true, margin: 0
});
slide3.addText("Real commercial demand exists despite hype-cycle skepticism.", {
  x: 0.5, y: 1.1, w: 9, h: 0.4, fontSize: 18, color: TEXT_MUTED, margin: 0
});

// Cards
const cards = [
  { title: "ChatGPT", stat: "Fastest", sub: "Growing app in history\nStrong PMF among devs" },
  { title: "Midjourney", stat: "$100M+", sub: "Reported revenue with a\nteam of just 11 people" },
  { title: "Character.ai", stat: "2 Hours", sub: "Average user session time\nin-app" }
];

cards.forEach((c, i) => {
  const cx = 0.5 + (i * 3.1);
  slide3.addShape(pres.shapes.RECTANGLE, {
    x: cx, y: 2.0, w: 2.8, h: 2.5, fill: { color: CARD_BG }, shadow: makeShadow(),
    line: { color: BORDER, width: 1 }
  });
  slide3.addShape(pres.shapes.RECTANGLE, {
    x: cx, y: 2.0, w: 2.8, h: 0.1, fill: { color: ACCENT_AI }
  });

  slide3.addText(c.title, {
    x: cx, y: 2.2, w: 2.8, h: 0.4, fontSize: 20, color: TEXT_LIGHT, bold: true, align: "center"
  });
  slide3.addText(c.stat, {
    x: cx, y: 2.8, w: 2.8, h: 0.6, fontSize: 36, color: ACCENT_AI, bold: true, align: "center"
  });
  slide3.addText(c.sub, {
    x: cx + 0.1, y: 3.6, w: 2.6, h: 0.8, fontSize: 14, color: TEXT_MUTED, align: "center", options: { breakLine: true }
  });
});


// --- SLIDE 4: Retention Gap ---
